SELECT count(*) FILTER (WHERE group_ko IN ('에이식스','더블원')) AS unit_planet, count(*) FILTER (WHERE with_groups && ARRAY['에이식스','더블원']::text[]) AS unit_with, count(*) FILTER (WHERE with_members && ARRAY['빛새온(솔로)','김민서(솔로)']::text[]) AS bdu_ghost, count(*) FILTER (WHERE group_ko='유앤비' AND with_members && ARRAY['강유찬(에이스)','고호정(핫샷)','준(유키스)']::text[]) AS unb_self FROM yt_channel_videos;

